ALIASES = {"helvetica": "arial", "arimo": "arial", "liberation sans": "arial", "times": "times new roman",
           "tinos": "times new roman", "liberation serif": "times new roman", "courier": "courier new",
           "cousine": "courier new", "liberation mono": "courier new", "gelasio": "georgia"}
_TABLES = {}


def advance_widths(font_family, bold=False):
    """{character: width per 1000 em} of a tabled font (case and spacing ignored, aliases resolved), else None."""
    if not isinstance(font_family, str):
        return None
    name = " ".join(font_family.lower().split())
    key = ALIASES.get(name, name) + (" bold" if bold else "")
    if key not in _DATA:
        return None
    if key not in _TABLES:
        ascii_widths, extra, extra_widths = _DATA[key]
        table = {chr(32 + i): int(w) for i, w in enumerate(ascii_widths.split(","))}
        table.update(zip(extra, map(int, extra_widths.split(","))))
        _TABLES[key] = table
    return _TABLES[key]
